//6:4  hsc pattern start
//2:0  hsc pattern end
#define VPP_HSC_INI_PAT_CTRL                       ((0x1d35  << 2) + 0xff800000)
#define VPP_SC_GCLK_CTRL                           ((0x1d36  << 2) + 0xff800000)
#define VPP_PREHSC_COEF                            ((0x1d37  << 2) + 0xff800000)
#define VPP_PRE_SCALE_CTRL                         ((0x1d38  << 2) + 0xff800000)
#define VPP_PREVSC_COEF                            ((0x1d39  << 2) + 0xff800000)
#define VPP_PREHSC_COEF1                           ((0x1d3a  << 2) + 0xff800000)
