// Bit 31:0 -- AUDIO_PTS
#define PARSER_B_AUDIO_PTS                         ((0x1175  << 2) + 0xfdf00000)
// Bit 31:0 -- AUDIO_PTS_WR_PTR
#define PARSER_B_AUDIO_PTS_WR_PTR                  ((0x1176  << 2) + 0xfdf00000)
